function base(c){return defineQuestionDefinition({courseScope:'y13',topicId,difficulty:'core',prerequisiteTags:['integration-as-area','signed-area','area-construction','integration-method-selection'],methodTags:[],vocabularyTags:['vocab:definite-integral','vocab:geometrical-area'],hintSequence:[{id:'h1',text:'Construct the region first: intersections, limits, top/bottom, split if needed. Choose the integration technique last.'}],...c});}
export const routineBetweenCurvesDefinition=base({templateId:'question-template:y13:integration:areas:routine',assessmentObjective:'ao1',microSkillId:skill('construct-region'),methodTags:[INTEGRATION_METHOD_TAGS.standard],responseType:'choice',responseLabel:'Correct setup',errorCategories:['limits','top-bottom'],diagnosticRules:{limits:{kind:'recognition',supportNeed:'understand',supportMicroSkillId:skill('construct-region'),studentMessage:'Use the intersection x-values as limits.'},'top-bottom':{kind:'recognition',supportNeed:'understand',supportMicroSkillId:skill('construct-region'),studentMessage:'Subtract lower curve from upper curve.'}},defaultDiagnostic:{kind:'recognition',supportNeed:'understand'},parameterGenerator:()=>({}),promptRenderer:()=>`The curves y=x+3 and y=x²−x+1 meet at x=0 and x=2. Which integral gives the enclosed area?`,responseOptionsRenderer:()=>[choice('a','∫₀²[(x+3)−(x²−x+1)]dx'),choice('b','∫₀²[(x²−x+1)−(x+3)]dx'),choice('c','∫₋₂²[(x+3)−(x²−x+1)]dx')],answerChecker:r=>r==='a'?ok():bad('top-bottom','Use the intersections 0 and 2, and top minus bottom.'),workedSolutionGenerator:()=>[step('1','Limits','x=0,2','Use the intersections.'),step('2','Order','top=x+3; bottom=x²−x+1','Check one x-value between the intersections.'),step('3','Construct','∫₀²[(x+3)−(x²−x+1)]dx','Only now integrate.')]});
export const splitRegionsDefinition=base({templateId:'question-template:y13:integration:areas:split',assessmentObjective:'ao1',microSkillId:skill('split-region'),responseType:'choice',responseLabel:'Split decision',errorCategories:['split'],diagnosticRules:{split:{kind:'recognition',supportNeed:'understand',supportMicroSkillId:skill('split-region'),studentMessage:'Split wherever the upper/lower order changes.'}},defaultDiagnostic:{kind:'recognition',supportNeed:'understand'},parameterGenerator:()=>({}),promptRenderer:()=>`Curves A and B enclose a region from x=−1 to x=1 and cross at x=0. A is above B on [−1,0], while B is above A on [0,1]. Which setup gives geometrical area?`,responseOptionsRenderer:()=>[choice('a','∫₋₁⁰(A−B)dx + ∫₀¹(B−A)dx'),choice('b','∫₋₁¹(A−B)dx'),choice('c','|∫₋₁¹(A−B)dx|')],answerChecker:r=>r==='a'?ok():bad('split','A single signed integral can cancel regions; split where the order changes.'),workedSolutionGenerator:()=>[step('1','Split point','x=0','The curve order changes here.'),step('2','Left','∫₋₁⁰(A−B)dx','A is on top.'),step('3','Right','∫₀¹(B−A)dx','B is on top.') ]});
export const advancedTechniqueDefinition=base({templateId:'question-template:y13:integration:areas:advanced',assessmentObjective:'ao1',microSkillId:skill('method-selection'),responseType:'choice',responseLabel:'Integration method',methodTags:[INTEGRATION_METHOD_TAGS.reverseChain,INTEGRATION_METHOD_TAGS.trigIdentity,INTEGRATION_METHOD_TAGS.substitution,INTEGRATION_METHOD_TAGS.byParts,INTEGRATION_METHOD_TAGS.partialFractions],errorCategories:['method-before-region'],diagnosticRules:{'method-before-region':{kind:'recognition',supportNeed:'understand',supportMicroSkillId:skill('method-selection'),studentMessage:'Construct the area integral before choosing the technique.'}},defaultDiagnostic:{kind:'recognition',supportNeed:'understand'},parameterGenerator:({random})=>({kind:random.pick(['reverse','trig','sub','parts','pf'])}),promptRenderer:p=>`After the region, intersections and top-minus-bottom setup are already correct, which method should be used for the remaining ${p.kind==='reverse'?'f′(x)e^{f(x)}':p.kind==='trig'?'sin²x':p.kind==='sub'?'x√(x²+1)':p.kind==='parts'?'xe^x':'rational function with factorised linear denominator'} integral?`,responseOptionsRenderer:p=>{const ans={reverse:INTEGRATION_METHOD_TAGS.reverseChain,trig:INTEGRATION_METHOD_TAGS.trigIdentity,sub:INTEGRATION_METHOD_TAGS.substitution,parts:INTEGRATION_METHOD_TAGS.byParts,pf:INTEGRATION_METHOD_TAGS.partialFractions}[p.kind];return [choice('a',getIntegrationMethodLabel(ans)),choice('b',getIntegrationMethodLabel(INTEGRATION_METHOD_TAGS.byParts)),choice('c',getIntegrationMethodLabel(INTEGRATION_METHOD_TAGS.standard))];},answerChecker:r=>r==='a'?ok():bad('method-before-region','Choose the method from the integrand only after the area construction is settled.'),workedSolutionGenerator:p=>[step('1','Area construction','already complete','Region decisions come first.'),step('2','Technique',({reverse:INTEGRATION_METHOD_TAGS.reverseChain,trig:INTEGRATION_METHOD_TAGS.trigIdentity,sub:INTEGRATION_METHOD_TAGS.substitution,parts:INTEGRATION_METHOD_TAGS.byParts,pf:INTEGRATION_METHOD_TAGS.partialFractions})[p.kind],'Now select the integration route.')]});
export const explainSplitsDefinition=base({templateId:'question-template:y13:integration:areas:explain-split',assessmentObjective:'ao2',microSkillId:skill('split-region'),responseType:'short-reasoning',responseLabel:'Explanation',placeholder:'Explain why the split is necessary.',errorCategories:['split'],diagnosticRules:{split:{kind:'recognition',supportNeed:'understand',supportMicroSkillId:skill('split-region'),studentMessage:'Refer to the change in which curve is upper.'}},defaultDiagnostic:{kind:'recognition',supportNeed:'understand'},parameterGenerator:()=>({}),promptRenderer:()=>`Explain why an area-between-curves calculation may need to be split at an intersection inside the interval.`,answerChecker:r=>{const t=String(r??'').toLowerCase();return (t.includes('top')||t.includes('upper'))&&(t.includes('change')||t.includes('swap')||t.includes('switch'))?ok():bad('split','State that top/bottom order changes, so the subtraction order must change.');},workedSolutionGenerator:()=>[step('1','Reason','upper/lower curves swap at the intersection','Top minus bottom must remain non-negative for each geometrical-area piece.')]});
