export const signedVsGeometricDefinition=base({templateId:'question-template:y13:integration:areas:signed',assessmentObjective:'ao2',microSkillId:skill('signed-vs-geometric'),responseType:'short-reasoning',responseLabel:'Interpretation',placeholder:'Explain the difference.',errorCategories:['signed-area'],diagnosticRules:{'signed-area':{kind:'recognition',supportNeed:'understand',supportMicroSkillId:skill('signed-vs-geometric'),studentMessage:'Signed integrals can cancel; geometrical area cannot.'}},defaultDiagnostic:{kind:'recognition',supportNeed:'understand'},parameterGenerator:()=>({}),promptRenderer:()=>`Why can a definite integral across two regions have value 0 while the total geometrical area is positive?`,answerChecker:r=>{const t=String(r??'').toLowerCase();return (t.includes('cancel')||t.includes('negative'))&&(t.includes('magnitude')||t.includes('area'))?ok():bad('signed-area','Mention signed cancellation and adding positive magnitudes for geometrical area.');},workedSolutionGenerator:()=>[step('1','Signed integral','positive and negative contributions may cancel','Orientation/sign is retained.'),step('2','Geometrical area','add magnitudes of pieces','Area is non-negative.')]});
